  doc.text("Consultorio Profesional", 105, 34, { align: "center" });
  doc.setLineWidth(0.5);
  doc.line(20, 40, 190, 40);
  doc.setFontSize(12);
  doc.setFont("helvetica", "bold");
  doc.text("Paciente:", 20, 50);
  doc.setFont("helvetica", "normal");
  doc.text(patient.name, 50, 50);
